-- The places reference table (#1699, part of #1698)
-- ---------------------------------------------------------------------------
--
-- What a `place` registration question is answered from: every US state,
-- county, city, town and CDP, plus NYC's boroughs and neighborhoods, seeded
-- from public data by the next migration (generated by `bun run places:seed`).
-- No third-party API is called at runtime, so a registrant's keystrokes never
-- leave our database and the picker costs nothing.
--
-- PLATFORM-WIDE, NOT PER TENANT. There is no tenant_id: a town is the same
-- town for every tenant. Anyone may read it, anon included, because the public
-- registration form searches it; nothing but a migration writes it (no write
-- grant to any client role, and no policy but select).
--
-- THE HIERARCHY is state -> county (or NYC borough) -> locality -> NYC
-- neighborhood (an NTA). A place that spans several counties hangs off the
-- first and lists the rest in area_ids, which holds the place's own id and
-- every place it lies within -- what a tenant's service area is compared
-- against.
--
-- IDS ARE STABLE. place_key_id() derives each id from a short key of the
-- source and its code ("place:3451000", "nta:BK0101"), so rebuilding the seed
-- from a newer vintage keeps every unchanged place's id. Answers copy the
-- label as shown anyway, so a place that later disappears never changes an
-- answer that named it.

create table public.places (
  id uuid primary key,
  kind text not null
    check (kind in ('state', 'county', 'borough', 'locality', 'neighborhood')),
  name text not null check (btrim(name) <> ''),
  -- The Census name's suffix as a type ("township", "borough", "CDP"...),
  -- null where there is none.
  place_type text,
  -- The words a registrant picks and an answer keeps: "Williamsburg,
  -- Brooklyn", "Montclair Twp, Essex Co., NJ".
  label text not null check (btrim(label) <> ''),
  parent_id uuid references public.places (id),
  area_ids uuid[] not null default '{}',
  state_code text not null,
  county_name text,
  source text not null,
  -- The source's own code: a Census GEOID or an NTA code.
  source_id text not null,
  aliases text[] not null default '{}',
  -- A Census estimate, for ranking only: what puts Newark, NJ ahead of
  -- Newark, AR. Null for CDPs; an NYC neighborhood has its borough's average.
  population integer,
  constraint places_source_key unique (source, source_id)
);

comment on table public.places is
  'Platform-wide reference list of US places (#1699): states, counties, NYC boroughs, cities/towns/CDPs (Census Gazetteer) and NYC neighborhoods (2020 NTAs). Answers to a place registration question name one. Not per tenant; readable by anyone; written only by migrations. Sources and vintages: docs/spec/events.md.';

-- Lower-cased name, label and aliases: what search_places() matches. A
-- function only so the generated column can use array_to_string, which is
-- not marked immutable in general but is for text[].
create function public.place_search_text(p_name text, p_label text, p_aliases text[])
returns text
language sql
immutable
parallel safe
as $$
  select lower(p_name || ' ' || p_label || ' ' || array_to_string(p_aliases, ' '));
$$;

alter table public.places
  add column search_text text not null
    generated always as (public.place_search_text(name, label, aliases)) stored;

create index places_search_text_trgm_idx
  on public.places using gin (search_text gin_trgm_ops);
create index places_parent_idx on public.places (parent_id);
create index places_kind_idx on public.places (kind);

alter table public.places enable row level security;

revoke all on public.places from public, anon, authenticated;
grant select on public.places to anon, authenticated;

create policy "places select" on public.places
  for select to anon, authenticated
  using (true);

-- The id a seed key maps to. Immutable, so the seed and anything that names a
-- place in a migration (a tenant's service area) agree without a lookup.
create function public.place_key_id(p_key text)
returns uuid
language sql
immutable
parallel safe
set search_path = public, extensions
as $$
  select case when p_key is null then null
    else extensions.uuid_generate_v5(extensions.uuid_ns_url(), 'https://coven.places/' || p_key)
  end;
$$;

comment on function public.place_key_id(text) is
  'The places.id for a seed key such as ''place:3451000'', ''county:36047'' or ''nta:BK0101'' (#1699): uuid v5, so a rebuilt seed keeps ids stable.';

-- ---------------------------------------------------------------------------
-- Search
-- ---------------------------------------------------------------------------

-- The autocomplete. At most 10 places where every word typed starts a word of
-- the name, label or an alias, of the kinds the granularity allows:
--
--   locality       cities, towns and CDPs, and NYC's boroughs
--   neighborhood   the same plus NYC neighborhoods; elsewhere it is the
--                  same list as locality, which is the fallback
--   area           states, counties and boroughs: what a service area is
--                  made of
--
-- Ranked: inside p_area first (a place is inside when it or anything it lies
-- within is listed), then an exact name, then a name that starts with what
-- was typed, then the larger population, then boroughs, municipalities and
-- neighborhoods ahead of CDPs, then the shorter label. With no area every place ranks equally on the
-- first key, so the whole US is searchable with nothing configured.
create function public.search_places(
  p_query text,
  p_granularity text,
  p_area uuid[] default null
) returns table (id uuid, kind text, label text, in_area boolean)
language plpgsql
stable
set search_path = public
as $$
declare
  v_query text := lower(btrim(regexp_replace(coalesce(p_query, ''), '[\s,]+', ' ', 'g')));
  v_words text[];
  v_longest text;
  v_patterns text[];
  v_kinds text[];
begin
  v_kinds := case p_granularity
    when 'locality' then array['locality', 'borough']
    when 'neighborhood' then array['locality', 'borough', 'neighborhood']
    when 'area' then array['state', 'county', 'borough']
  end;
  if v_kinds is null then
    raise exception 'PLACE_GRANULARITY_INVALID';
  end if;

  if char_length(v_query) < 2 or char_length(v_query) > 100 then
    return;
  end if;
  v_words := string_to_array(v_query, ' ');
  select w into v_longest from unnest(v_words) w order by char_length(w) desc limit 1;
  -- Each word at a word start, with regex metacharacters escaped. The LIKE
  -- on the longest word is what the trigram index serves.
  select array_agg('(^|[^[:alnum:]])' || regexp_replace(w, '([^[:alnum:][:space:]])', '\\\1', 'g'))
    into v_patterns
    from unnest(v_words) w;
  v_longest := replace(replace(replace(v_longest, '\', '\\'), '%', '\%'), '_', '\_');

  return query
  select p.id, p.kind, p.label, coalesce(p.area_ids && p_area, false)
    from public.places p
   where p.kind = any (v_kinds)
     and p.search_text like '%' || v_longest || '%'
     and not exists (
       select 1 from unnest(v_patterns) w where p.search_text !~ w
     )
   order by
     coalesce(p.area_ids && p_area, false) desc,
     (lower(p.name) = v_query or v_query = any (select lower(a) from unnest(p.aliases) a)) desc,
     (lower(p.name) like v_query || '%'
       or exists (select 1 from unnest(p.aliases) a where lower(a) like v_query || '%')) desc,
     p.population desc nulls last,
     case
       when p.kind in ('state', 'borough') then 0
       when p.kind = 'locality' and p.place_type = 'CDP' then 2
       else 1
     end,
     char_length(p.label),
     p.label
   limit 10;
end;
$$;

comment on function public.search_places(text, text, uuid[]) is
  'Place autocomplete (#1699): at most 10 places matching every word typed, of the kinds p_granularity allows (locality, neighborhood or area), places within p_area first. Raises PLACE_GRANULARITY_INVALID. Reads only the public places table, so it runs as the caller.';

revoke execute on function public.search_places(text, text, uuid[]) from public;
grant execute on function public.search_places(text, text, uuid[]) to anon, authenticated;
